class KeywordProcessor:
    def __init__(self, case_sensitive=False):
        self._keyword = {}
        self._case_sensitive = case_sensitive
        self.non_word_boundaries = set()
        self._white_space_chars = set([" ", "\t", "\n"])

    def __len__(self):
        return len(self._keyword)

    def __contains__(self, word):
        return word in self._keyword

    def __getitem__(self, word):
        return self._keyword[word]

    def __setitem__(self, word, clean_name):
        self._keyword[word] = clean_name
